variable_spec_hash <- function(spec) { x <- spec[c("id","short_name","dataset_short_name","cds_variable","netcdf_variable_names","source_units","output_units","daily_statistic","time_zone","frequency","unit_conversion","spatial_interpolation","weekly_statistic","hard_valid_range","soft_warning_range","soil_layer")]; digest::digest(x, algo="xxhash32") }
.variable_spec_mintemp <- function() { x <- list(id="era5_mintemp", short_name="mintemp", long_name="2 metre temperature", dataset_short_name="derived-era5-single-levels-daily-statistics", cds_variable="2m_temperature", netcdf_variable_names=c("t2m","2m_temperature"), source_units="K", output_units="degrees C", soil_layer=NULL, daily_statistic="daily_minimum", time_zone="utc+00:00", frequency="6_hourly", unit_conversion="kelvin_to_celsius", spatial_interpolation="bilinear", weekly_statistic="minimum", hard_valid_range=c(-100,70), soft_warning_range=NULL, daily_filename_prefix="mintemp", weekly_filename_prefix="mintemp"); x$variable_spec_hash <- variable_spec_hash(x); x }
.variable_spec_soilmoist <- function() { x <- list(id="era5_soilmoist", short_name="soilmoist", long_name="Volumetric soil water layer 1", dataset_short_name="derived-era5-single-levels-daily-statistics", cds_variable="volumetric_soil_water_layer_1", netcdf_variable_names=c("swvl1","volumetric_soil_water_layer_1"), source_units="m3 m-3", output_units="m3 m-3", soil_layer=list(top_cm=0,bottom_cm=7), daily_statistic="daily_mean", time_zone="utc+00:00", frequency="6_hourly", unit_conversion="identity", spatial_interpolation="bilinear", weekly_statistic="mean", hard_valid_range=c(0,1), soft_warning_range=c(0.01,0.80), daily_filename_prefix="soilmoist", weekly_filename_prefix="soilmoist"); x$variable_spec_hash <- variable_spec_hash(x); x }
.variable_spec_lai_low <- function() { x <- list(id="era5_lai_low", short_name="lai_low", long_name="Leaf area index, low vegetation", dataset_short_name="reanalysis-era5-single-levels", cds_variable="leaf_area_index_low_vegetation", netcdf_variable_names=c("lai_lv","leaf_area_index_low_vegetation"), source_units="m2 m-2", output_units="m2 m-2", soil_layer=NULL, daily_statistic="instantaneous_00_utc", time_zone="utc+00:00", frequency="monthly", unit_conversion="identity", spatial_interpolation="bilinear", weekly_statistic="mean", hard_valid_range=c(0,20), source_hard_valid_range=c(-0.01,20), soft_warning_range=NULL, daily_filename_prefix="lai_low", weekly_filename_prefix="lai_low", dataset_adapter="era5", product_type="direct", temporal_character="monthly_climatology", interannual_variability="absent", source_grid_degrees=0.25); x$variable_spec_hash <- variable_spec_hash(x); x }
.variable_spec_relhum_min <- function() { x <- list(id="agera5_relhum_min", short_name="relhum_min", long_name="2 m relative humidity derived, 24-hour minimum", dataset_short_name="sis-agrometeorological-indicators", cds_variable="2m_relative_humidity_derived", netcdf_variable_names=c("relhum_min","relative_humidity_2m_min","2m_relative_humidity_derived","RHmin"), source_units="percent", output_units="percent", soil_layer=NULL, daily_statistic="24_hour_minimum", time_zone="local_time", frequency="daily", unit_conversion="identity", spatial_interpolation="bilinear", weekly_statistic="mean", hard_valid_range=c(0,100), source_hard_valid_range=c(-1,101), soft_warning_range=NULL, daily_filename_prefix="relhum_min", weekly_filename_prefix="relhum_min", dataset_adapter="agera5", product_type="direct_precomputed_derived_indicator", source_family="AgERA5", source_grid_degrees=0.1, daily_time_basis="local_time", spatial_processing="AgERA5_downscaled_bias_adjusted", model_alias="relhum"); x$variable_spec_hash <- variable_spec_hash(x); x }
get_variable_spec <- function(variable_id, config=NULL) { id <- as.character(variable_id %||% if(!is.null(config)) config$project$dataset_id else ""); if(id %in% c("era5_mintemp","mintemp","2m_temperature","t2m")) return(.variable_spec_mintemp()); if(id %in% c("era5_soilmoist","soilmoist","volumetric_soil_water_layer_1")) return(.variable_spec_soilmoist()); if(id %in% c("era5_lai_low","lai_low","leaf_area_index_low_vegetation","lai_lv")) return(.variable_spec_lai_low()); if(id %in% c("agera5_relhum_min","relhum_min","relhum","2m_relative_humidity_derived")) return(.variable_spec_relhum_min()); stop("Unknown variable_id: ", id, call.=FALSE) }
resolve_netcdf_variable <- function(nc_metadata, variable_spec) { candidates <- intersect(variable_spec$netcdf_variable_names, names(nc_metadata$variables)); if(!length(candidates)) stop("No NetCDF variable matched aliases: ", paste(variable_spec$netcdf_variable_names, collapse=", "), call.=FALSE); if(length(candidates)>1L) { a <- lapply(candidates, function(n) nc_metadata$variables[[n]]$data_signature %||% nc_metadata$variables[[n]]$dimensions); if(!identical(a[[1]],a[[2]])) stop("NetCDF variable aliases are ambiguous and refer to different data",call.=FALSE) }; candidates[[1]] }
normalize_source_units <- function(units) { if(length(units)!=1L||is.na(units)||!nzchar(trimws(units))) return(NA_character_); x<-trimws(as.character(units)); x<-chartr("\u2070\u00b9\u00b2\u00b3\u2074\u2075\u2076\u2077\u2078\u2079\u207b","0123456789-",x); x<-gsub("[\u00d7\u00b7\u22c5]"," ",x); x<-gsub("[[:space:]]+"," ",x); x<-gsub("\\s*[/]\\s*","/",x); x<-gsub("\\s*[\\^]\\s*","^",x); x<-gsub("\\*\\*","^",x); x<-tolower(trimws(x)); if(x%in%c("1","1/1","dimensionless"))return("m3 m-3"); if(x%in%c("m2/m2","m^2/m^2","m2 m-2","m^2 m^-2","m^2 m-2"))return("m2 m-2"); if(x%in%c("%","percent","percentage"))return("percent"); if(x%in%c("m3/m3","m^3/m^3","m3 m-3","m^3 m^-3","m^3 m-3","m3 m^ -3"))return("m3 m-3"); if(x%in%c("k","kelvin"))return("K"); x }
convert_source_units <- function(x, variable_spec, source_units=NULL) { expected <- normalize_source_units(variable_spec$source_units); actual <- normalize_source_units(source_units); lai_dimensionless <- variable_spec$id=="era5_lai_low" && tolower(trimws(as.character(source_units%||%"")))%in%c("1","dimensionless"); if(!is.null(source_units)&&!identical(actual,expected)&&!lai_dimensionless)stop("Unsupported source units: ",source_units,call.=FALSE); if(variable_spec$unit_conversion=="kelvin_to_celsius")return(x-273.15); if(variable_spec$unit_conversion=="identity")return(x); stop("Unsupported unit conversion: ",variable_spec$unit_conversion,call.=FALSE) }
validate_source_values <- function(x, variable_spec, source_hard_min=variable_spec$source_hard_valid_range[1] %||% -Inf, source_hard_max=variable_spec$source_hard_valid_range[2] %||% Inf) { z<-as.numeric(x);z<-z[is.finite(z)];if(!length(z))stop("Source variable has no finite values",call.=FALSE);if(any(z<source_hard_min|z>source_hard_max))stop("Source values outside sanity range [",source_hard_min,", ",source_hard_max,"]",call.=FALSE);list(source_minimum=min(z),source_maximum=max(z),source_non_na_count=length(z),source_hard_range_valid=TRUE) }
validate_variable_value_range <- function(x, variable_spec) { if(is.character(x)&&length(x)==1L&&file.exists(x))x<-terra::rast(x); z<-if(inherits(x,"SpatRaster"))as.numeric(terra::values(x,mat=FALSE))else as.numeric(x); finite<-is.finite(z); hard<-as.numeric(variable_spec$hard_valid_range); valid_values<-z[finite]; below<-sum(valid_values<hard[1]); above<-sum(valid_values>hard[2]); nonfinite_non_na<-sum(!finite & !is.na(z)); valid<-length(valid_values)>0L&&!below&&!above&&!nonfinite_non_na; list(valid=valid,expected_minimum=hard[1],expected_maximum=hard[2],observed_minimum=if(length(valid_values))min(valid_values)else NA_real_,observed_maximum=if(length(valid_values))max(valid_values)else NA_real_,below_count=below,above_count=above,total_cells=length(z),finite_non_nodata_cells=length(valid_values),na_nodata_cells=sum(is.na(z)),nonfinite_non_na_cells=nonfinite_non_na,message=if(valid)"ok"else sprintf("value range invalid: observed_min=%s observed_max=%s expected_min=%s expected_max=%s below_count=%d above_count=%d",format(if(length(valid_values))min(valid_values)else NA_real_,trim=TRUE),format(if(length(valid_values))max(valid_values)else NA_real_,trim=TRUE),hard[1],hard[2],below,above)) }
validate_variable_values <- function(x, variable_spec, tolerance=1e-6) { z<-as.numeric(x);finite<-is.finite(z);hard<-variable_spec$hard_valid_range;if(variable_spec$id=="era5_soilmoist"){z[finite&z<hard[1]&z>=hard[1]-tolerance]<-hard[1];z[finite&z>hard[2]&z<=hard[2]+tolerance]<-hard[2]};range_check<-validate_variable_value_range(z,variable_spec);hard_valid<-range_check$valid;warning_range<-variable_spec$soft_warning_range;soft_warning<-!is.null(warning_range)&&any(finite&(z<warning_range[1]|z>warning_range[2]));if(!hard_valid)stop("Values outside hard valid range [",hard[1],", ",hard[2],"]",call.=FALSE);qs<-if(any(finite))stats::quantile(z[finite],probs=c(0,.25,.5,.75,1),names=FALSE,na.rm=TRUE)else rep(NA_real_,5);list(values=z,minimum=if(any(finite))min(z[finite])else NA_real_,maximum=if(any(finite))max(z[finite])else NA_real_,mean=if(any(finite))mean(z[finite])else NA_real_,standard_deviation=if(sum(finite)>1)stats::sd(z[finite])else NA_real_,quantiles=qs,hard_range_valid=hard_valid,soft_range_warning=soft_warning,non_na_count=sum(finite)) }
normalize_output_values <- function(x, variable_spec, config=NULL) { if (!(variable_spec$id %in% c("era5_soilmoist","era5_lai_low","agera5_relhum_min"))) return(validate_variable_values(x,variable_spec)); z<-as.numeric(x); finite<-is.finite(z); v<-if(is.null(config)) list() else (config$validation %||% list()); minv<-v$physical_minimum %||% v$physical_minimum_percent %||% variable_spec$hard_valid_range[1]; maxv<-v$physical_maximum %||% v$physical_maximum_percent %||% variable_spec$hard_valid_range[2]; tol<-v$clamp_tolerance %||% v$clamp_tolerance_percent %||% if(variable_spec$id=="era5_lai_low") 0.01 else if(variable_spec$id=="agera5_relhum_min") 0.5 else 0.01; before<-z[finite]; if(any(before<minv-tol|before>maxv+tol)) stop("Final values outside physical tolerance",call.=FALSE); low<-finite&z<minv; high<-finite&z>maxv; low_adj<-if(any(low))max(abs(z[low]-minv))else 0; high_adj<-if(any(high))max(abs(z[high]-maxv))else 0; z[low]<-minv; z[high]<-maxv; final<-z[is.finite(z)]; if(length(final)&&any(final<minv|final>maxv))stop("Final values outside physical range",call.=FALSE); list(values=z,projected_masked_minimum_before_clamp=if(length(before))min(before)else NA_real_,projected_masked_maximum_before_clamp=if(length(before))max(before)else NA_real_,projected_minimum_before_adjustment=if(length(before))min(before)else NA_real_,projected_maximum_before_adjustment=if(length(before))max(before)else NA_real_,cells_adjusted_low=sum(low),cells_clamped_low=sum(low),cells_clamped_high=sum(high),largest_low_adjustment=low_adj,largest_high_adjustment=high_adj,final_minimum=if(length(final))min(final)else NA_real_,final_maximum=if(length(final))max(final)else NA_real_,non_na_count=length(final),hard_range_valid=TRUE,soft_range_warning=FALSE) }
aggregate_daily_values <- function(rasters, variable_spec) { if(variable_spec$daily_statistic=="daily_minimum")return(terra::app(terra::rast(rasters),fun=min,na.rm=TRUE));if(variable_spec$daily_statistic=="daily_mean")return(terra::app(terra::rast(rasters),fun=mean,na.rm=FALSE));stop("Unsupported daily statistic: ",variable_spec$daily_statistic,call.=FALSE) }
aggregate_weekly_values <- function(rasters, variable_spec) { if(variable_spec$weekly_statistic=="minimum")return(terra::app(terra::rast(rasters),fun=min,na.rm=TRUE));if(variable_spec$weekly_statistic=="mean")return(terra::app(terra::rast(rasters),fun=mean,na.rm=FALSE));stop("Unsupported weekly statistic: ",variable_spec$weekly_statistic,call.=FALSE) }
daily_output_filename <- function(variable_spec,date,estimated=FALSE)format_daily_filename(variable_spec$daily_filename_prefix,date,estimated)
weekly_output_filename <- function(variable_spec,iso_year,iso_week,estimated=FALSE)format_weekly_filename(variable_spec$weekly_filename_prefix,iso_year,iso_week,estimated)
